-- Penambahan non-destruktif. Jalankan satu kali; aman dijalankan ulang.
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT OR IGNORE INTO app_settings VALUES ('academicYearStart','2026');
INSERT OR IGNORE INTO app_settings VALUES ('semester','1');
CREATE TABLE IF NOT EXISTS sk_staff (source_key TEXT PRIMARY KEY, source_no INTEGER NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, position TEXT NOT NULL DEFAULT '', source_class TEXT NOT NULL DEFAULT '', source_subject TEXT NOT NULL DEFAULT '', total_jp INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', teacher_id TEXT REFERENCES teachers(id), academic_year TEXT NOT NULL, semester INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS teaching_assignments (id TEXT PRIMARY KEY, source_key TEXT NOT NULL REFERENCES sk_staff(source_key), teacher_id TEXT NOT NULL REFERENCES teachers(id), subject TEXT NOT NULL, source_class TEXT NOT NULL, jp INTEGER NOT NULL, academic_year TEXT NOT NULL, semester INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS _sk_import_guard (ok INTEGER NOT NULL CHECK(ok=1));
DELETE FROM _sk_import_guard;
